import {styleTags, tags as t} from "@lezer/highlight"

export const cHighlighting = styleTags({
  "typedef struct union enum": t.definitionKeyword,
  "extern static auto register thread_local _Thread_local inline const volatile restrict _Atomic": t.modifier,
  "if else switch for while do case default return break continue goto": t.controlKeyword,
  "sizeof _Alignof __alignof__ _Generic _Static_assert static_assert": t.operatorKeyword,
  "NULL": t.null,
  "true false": t.bool,
  "PrimitiveType TypeSize": t.typeName,
  TypeIdentifier: t.typeName,
  FieldIdentifier: t.propertyName,
  "CallExpression/FieldExpression/FieldIdentifier": t.function(t.propertyName),
  StatementIdentifier: t.labelName,
  "Identifier": t.variableName,
  "CallExpression/Identifier": t.function(t.variableName),
  "FunctionDeclarator/Identifier": t.function(t.definition(t.variableName)),
  ArithOp: t.arithmeticOperator,
  LogicOp: t.logicOperator,
  BitOp: t.bitwiseOperator,
  CompareOp: t.compareOperator,
  UpdateOp: t.updateOperator,
  LineComment: t.lineComment,
  BlockComment: t.blockComment,
  Number: t.number,
  String: t.string,
  SystemLibString: t.special(t.string),
  CharLiteral: t.character,
  EscapeSequence: t.escape,
  PreprocArg: t.meta,
  "PreprocDirectiveName #include #ifdef #ifndef #if #define #else #endif #elif": t.processingInstruction,
  "( )": t.paren,
  "[ ]": t.squareBracket,
  "{ }": t.brace,
  ". ->": t.derefOperator,
  ", ;": t.separator
})
